            './common/buildEncodedConfig.js': buildEncodedConfigModule,
            './common/machineAuthor.js': machineAuthorModule,
            './common/smProvider.js': {
                createSmProvider: function () {
                    return {
                        prStatus: function () {
                            return (opts.github && opts.github.prStatus) || null;
                        }
                    };
